// app/smartmeter/[id]/edit/page.tsx
// Updated Add smartmeter Page with Backend Integration
"use client";

import type React from "react";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { DashboardHeader } from "@/components/dashboard-header";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import MediaConverterCard from "@/components/smartmeter/mediaConverterCard";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import { ArrowLeft, Save, MapPin, Loader2 } from "lucide-react";
import { getSmartMeterById, updateSmartMeter } from "@/lib/api/smartmeter";
import { useToast } from "@/hooks/use-toast";
import { useParams } from "next/navigation";

export default function EditSmartMeterPage() {
  const params = useParams();
  const router = useRouter();
  const { toast } = useToast();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);

  const [formData, setFormData] = useState({
    smartMeterId: "",
    addedBy: "",
    location: "",
    latitude: "",
    longitude: "",
    ipAddress: "",
    status: "Active",
    mediaConverters: [
      {
        mediaConverterId: "",

        left1Label: "FX",
        left2Label: "TX",
        left3Label: "LINK",
        right1Label: "PWR",
        right2Label: "ACT",
        right3Label: "FDX",
      },
    ],
  });

  const [validationErrors, setValidationErrors] = useState({
    smartMeterId: "",
    latitude: "",
    longitude: "",
    ipAddress: "",
  });

  useEffect(() => {
    if (params.id) {
      fetchSmartMeter();
    }
  }, [params.id]);

  const fetchSmartMeter = async () => {
    try {
      const response = await getSmartMeterById(params.id as string, true);

      

      if (response.success && response.data) {
        const meter = response.data;

        setFormData({
          smartMeterId: meter.smartMeterId || "",
          addedBy: meter.addedBy || "",
          location: meter.location || "",
          latitude: meter.latitude?.toString() || "",
          longitude: meter.longitude?.toString() || "",
          ipAddress: meter.ipAddress || "",
          status: meter.status || "Active",
          mediaConverters:
            meter.mediaConverters?.map((mc) => ({
              mediaConverterId: mc.mediaConverterId,

              left1Label: mc.left1Label,
              left2Label: mc.left2Label,
              left3Label: mc.left3Label,
              right1Label: mc.right1Label,
              right2Label: mc.right2Label,
              right3Label: mc.right3Label,
            })) || [],
        });
      }
    } finally {
      setLoading(false);
    }
  };

  const validateForm = () => {
    //function for validating ip
    const isValidIP = (ip: string) => {
      const ipRegex =
        /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;

      return ipRegex.test(ip);
    };

    const errors = {
      smartMeterId: "",
      latitude: "",
      longitude: "",
      ipAddress: "",
    };

    let isValid = true;

    if (
      formData.mediaConverters.length === 2 &&
      formData.mediaConverters[0].mediaConverterId.trim() &&
      formData.mediaConverters[1].mediaConverterId.trim() &&
      formData.mediaConverters[0].mediaConverterId.trim() ===
        formData.mediaConverters[1].mediaConverterId.trim()
    ) {
      toast({
        title: "Validation Error",
        description: "Both Media Converter IDs cannot be the same",
        variant: "destructive",
      });

      isValid = false;
    }

    if (!isValidIP(formData.ipAddress)) {
      errors.ipAddress = "Enter Valid IP Address";
      isValid = false;
    }

    const lat = parseFloat(formData.latitude);
    if (!formData.latitude) {
      errors.latitude = "Latitude is required";
      isValid = false;
    } else if (isNaN(lat) || lat < -90 || lat > 90) {
      errors.latitude = "Latitude must be between -90 and 90";
      isValid = false;
    }

    // Validate Longitude
    const lng = parseFloat(formData.longitude);
    if (!formData.longitude) {
      errors.longitude = "Longitude is required";
      isValid = false;
    } else if (isNaN(lng) || lng < -180 || lng > 180) {
      errors.longitude = "Longitude must be between -180 and 180";
      isValid = false;
    }

    if (!formData.smartMeterId.trim()) {
      errors.smartMeterId = "Smart Meter ID is required";
      isValid = false;
    }

    setValidationErrors(errors);

    return isValid;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    console.log("SUBMIT CLICKED");

    // Validate form
    if (!validateForm()) {
      toast({
        title: "Validation Error",
        description: "Please check the form for errors",
        variant: "destructive",
      });
      return;
    }

    setIsSubmitting(true);

    try {
      console.log(formData.addedBy);
      const response = await updateSmartMeter(params.id as string, {
        smartMeterId: formData.smartMeterId,
        location: formData.location,
        latitude: parseFloat(formData.latitude),
        longitude: parseFloat(formData.longitude),
        status: formData.status,
        ipAddress: formData.ipAddress,
        mediaConverters: formData.mediaConverters,
      });

      console.log("Create Response:", response);

      if (response.success) {
        toast({
          title: "Success",
          description: `SmartMeter "${formData.smartMeterId}" updated successfully`,
        });

        router.push(`/smartmeter/${params.id}`);
        router.refresh();
      } else {
        if (response.error?.toLowerCase().includes("media converter")) {
          setValidationErrors((prev) => ({
            ...prev,
            mediaConverterId: response.error,
          }));

          toast({
            title: "Duplicate Media Converter",
            description: response.error,
            variant: "destructive",
          });

          return;
        } else if (response.error?.toLowerCase().includes("smart meter")) {
          setValidationErrors((prev) => ({
            ...prev,
            smartMeterId: response.error,
          }));

          toast({
            title: "Duplicate Smart Meter",
            description: response.error,
            variant: "destructive",
          });

          return;
        } else {
          toast({
            title: "Error",
            description: response.error || "Failed to create Smart Meter",
            variant: "destructive",
          });
        }
      }
    } catch (err) {
      toast({
        title: "Error",
        description: "Failed to create SmartMeter. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleFieldChange = (field: string, value: string) => {
    setFormData({ ...formData, [field]: value });
    // Clear validation error when user starts typing
    setValidationErrors({ ...validationErrors, [field]: "" });
  };

  if (loading) {
  return (
    <div className="flex h-[70vh] items-center justify-center">

      <Loader2 className="h-8 w-8 animate-spin text-white" />

    </div>
  );
}
  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-2xl">
        {/* Back Button */}
        <Link
          href="/smartmeter"
          className="mb-6 inline-flex items-center gap-2 text-gray-400 hover:text-white"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to SmartMeter
        </Link>

        <Card className="border-[#333] bg-[#222]">
          <CardHeader>
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#8B0000]">
                <MapPin className="h-5 w-5 text-white" />
              </div>
              <div>
                <CardTitle className="text-xl text-white">
                  Edit SmartMeter
                </CardTitle>
                <CardDescription className="text-gray-400">
                  Update SmartMeter details
                </CardDescription>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid gap-6 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="smartMeterId" className="text-gray-300">
                    Smart Meter ID <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="smartMeterId"
                    placeholder="e.g., SM-006"
                    value={formData.smartMeterId}
                    onChange={(e) =>
                      handleFieldChange("smartMeterId", e.target.value)
                    }
                    required
                    className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                  />
                  {validationErrors.smartMeterId ? (
                    <p className="text-xs text-red-500">
                      {validationErrors.smartMeterId}
                    </p>
                  ) : (
                    <p className="text-xs text-gray-500">
                      Unique identifier for the smartmeter
                    </p>
                  )}
                </div>
                <div className="space-y-2">
                  <Label htmlFor="status" className="text-gray-300">
                    Status
                  </Label>
                  <Select
                    value={formData.status}
                    onValueChange={(value) =>
                      setFormData({ ...formData, status: value })
                    }
                  >
                    <SelectTrigger className="border-[#333] bg-[#1a1a1a] text-white focus:ring-[#8B0000]">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className="border-[#333] bg-[#222]">
                      <SelectItem
                        value="Active"
                        className="text-white focus:bg-[#333] focus:text-white"
                      >
                        Active
                      </SelectItem>
                      <SelectItem
                        value="Inactive"
                        className="text-white focus:bg-[#333] focus:text-white"
                      >
                        Inactive
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid gap-6 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="ipAddress" className="text-gray-300">
                    IP Address<span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="ipAddress"
                    placeholder="192.169.1.10"
                    value={formData.ipAddress}
                    onChange={(e) =>
                      handleFieldChange("ipAddress", e.target.value)
                    }
                    required
                    className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                  />
                  {validationErrors.ipAddress ? (
                    <p className="text-xs text-red-500">
                      {validationErrors.ipAddress}
                    </p>
                  ) : (
                    <p className="text-xs text-gray-500">Range: -90 to 90</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="addedBy" className="text-gray-300">
                    Added By <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="addedBy"
                    placeholder="Operator Name"
                    value={formData.addedBy}
                    onChange={(e) => {
                      handleFieldChange("addedBy", e.target.value);
                    }}
                    required
                    className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="Location" className="text-gray-300">
                  Location <span className="text-red-500">*</span>
                </Label>
                <Input
                  id="Location"
                  placeholder="Location"
                  value={formData.location}
                  onChange={(e) =>
                    handleFieldChange("location", e.target.value)
                  }
                  required
                  className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                />
              </div>

              <div className="grid gap-6 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="latitude" className="text-gray-300">
                    Latitude <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="latitude"
                    type="number"
                    step="any"
                    placeholder="e.g., 28.6139"
                    value={formData.latitude}
                    onChange={(e) =>
                      handleFieldChange("latitude", e.target.value)
                    }
                    required
                    className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                  />
                  {validationErrors.latitude ? (
                    <p className="text-xs text-red-500">
                      {validationErrors.latitude}
                    </p>
                  ) : (
                    <p className="text-xs text-gray-500">Range: -90 to 90</p>
                  )}
                </div>
                <div className="space-y-2">
                  <Label htmlFor="longitude" className="text-gray-300">
                    Longitude <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="longitude"
                    type="number"
                    step="any"
                    placeholder="e.g., 77.2090"
                    value={formData.longitude}
                    onChange={(e) =>
                      handleFieldChange("longitude", e.target.value)
                    }
                    required
                    className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                  />
                  {validationErrors.longitude ? (
                    <p className="text-xs text-red-500">
                      {validationErrors.longitude}
                    </p>
                  ) : (
                    <p className="text-xs text-gray-500">Range: -180 to 180</p>
                  )}
                </div>
              </div>

              {/* Media Converters */}
              <div className="space-y-5 border-t border-[#333] pt-6">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="text-lg font-semibold text-white">
                      Media Converters
                    </h3>

                    <p className="text-sm text-gray-400">
                      Maximum 2 converters can be attached to a Smart Meter
                    </p>
                  </div>

                  {formData.mediaConverters.length < 2 && (
                    <Button
                      type="button"
                      onClick={() =>
                        setFormData({
                          ...formData,
                          mediaConverters: [
                            ...formData.mediaConverters,
                            {
                              mediaConverterId: "",
                            },
                          ],
                        })
                      }
                      className="bg-[#8B0000] text-white hover:bg-[#6B0000]"
                    >
                      + Add Converter
                    </Button>
                  )}
                </div>

                <div className="grid gap-4">
                  {formData.mediaConverters.map((converter, index) => (
                    <div
                      key={index}
                      className="
                            rounded-2xl
                            border border-[#333]
                            bg-[#1a1a1a]
                            p-5
                            transition-all
                            hover:border-[#8B0000]/50
                          "
                    >
                      {/* Header */}
                      <div className="mb-5 flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <div
                            className="
                              flex h-10 w-10 items-center justify-center
                              rounded-xl
                              bg-[#8B0000]/20
                              text-[#ff6b6b]
                              font-bold
                            "
                          >
                            {index + 1}
                          </div>

                          <div>
                            <h4 className="font-semibold text-white">
                              Media Converter {index + 1}
                            </h4>
                          </div>
                        </div>

                        {index > 0 && (
                          <button
                            type="button"
                            onClick={() => {
                              const updated = formData.mediaConverters.filter(
                                (_, i) => i !== index,
                              );

                              setFormData({
                                ...formData,
                                mediaConverters: updated,
                              });
                            }}
                            className="
                              rounded-lg
                              border border-red-500/20
                              bg-red-500/10
                              px-3 py-1.5
                              text-sm
                              text-red-400
                              transition
                              hover:bg-red-500/20
                            "
                          >
                            Remove
                          </button>
                        )}
                      </div>
                      <div className="space-y-6">


    <MediaConverterCard
      key={index}
      index={index}
      converter={converter}
      removable={index > 0}

      onRemove={() => {

        const updated =
          formData.mediaConverters.filter(
            (_, i) => i !== index
          );

        setFormData({
          ...formData,
          mediaConverters: updated,
        });

      }}

      onIdChange={(id) => {

        const updated = [
          ...formData.mediaConverters,
        ];

        updated[index].mediaConverterId = id;

        setFormData({
          ...formData,
          mediaConverters: updated,
        });

      }}

      onMappingChange={(mapping) => {

        const updated = [
          ...formData.mediaConverters,
        ];

        updated[index] = {
          ...updated[index],
          ...mapping,
        };

        setFormData({
          ...formData,
          mediaConverters: updated,
        });

      }}

    />

  

</div>

                      {/* Inputs */}
                      {/* <div className="grid gap-4 md:grid-cols-2">
                        <div>
                          <Label className="mb-2 block text-gray-300">
                            Converter ID
                          </Label>

                          <Input
                            required
                            value={converter.mediaConverterId}
                            onChange={(e) => {
                              const updated = [...formData.mediaConverters];

                              updated[index].mediaConverterId = e.target.value;

                              setFormData({
                                ...formData,
                                mediaConverters: updated,
                              });

                              setValidationErrors((prev) => ({
                                ...prev,
                                mediaConverterId: "",
                              }));
                            }}
                            placeholder="MC-001"
                            className="
                              border-[#333]
                              bg-[#111]
                              text-white
                              focus:border-[#8B0000]
                            "
                          />
                        </div>

                        {/* <div>
                          <Label className="mb-2 block text-gray-300">
                            IP Address
                          </Label>

                          <Input
                            required
                            value={converter.ipAddress}
                            onChange={(e) => {
                              const updated = [...formData.mediaConverters];

                              updated[index].ipAddress = e.target.value;

                              setFormData({
                                ...formData,
                                mediaConverters: updated,
                              });
                            }}
                            placeholder="192.168.1.10"
                            className="
                              border-[#333]
                              bg-[#111]
                              text-white
                              focus:border-[#8B0000]
                            "
                          />

                         
                        </div> */}
                      {/* </div> */}
                    </div>
                  ))}
                </div> 
              </div>

              <div className="flex flex-col-reverse gap-3 pt-4 sm:flex-row sm:justify-end">
                <Link href="/smartmeter">
                  <Button
                    type="button"
                    variant="outline"
                    disabled={isSubmitting}
                    className="w-full border-[#333] bg-transparent text-white hover:bg-[#333] sm:w-auto"
                  >
                    Cancel
                  </Button>
                </Link>
                <Button
                  type="submit"
                  disabled={isSubmitting}
                  className="w-full gap-2 bg-[#8B0000] text-white hover:bg-[#6B0000] disabled:opacity-50 sm:w-auto"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="h-4 w-4" />
                      Save Changes
                    </>
                  )}
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
