"use client";

import { Trash2, Cpu } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import LedMapping, {
  LedMappingData,
} from "./ledMappingedMapping";

interface MediaConverter {
  mediaConverterId: string;

  left1Label: any;
  left2Label: any;
  left3Label: any;
  right1Label: any;
  right2Label: any;
  right3Label: any;
}

interface Props {
  index: number;
  converter: MediaConverter;

  onIdChange: (id: string) => void;

  onMappingChange: (
    mapping: LedMappingData
  ) => void;

  onRemove: () => void;

  removable: boolean;
}

export default function MediaConverterCard({
  index,
  converter,
  onIdChange,
  onMappingChange,
  onRemove,
  removable,
}: Props) {
  return (
    <div className="rounded-3xl border border-[#303030] bg-gradient-to-br from-[#171717] to-[#0d0d0d] p-6 shadow-xl">

      {/* Header */}

      <div className="mb-6 flex items-center justify-between">

        <div className="flex items-center gap-4">

          <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-[#8B0000]/15">

            <Cpu className="h-6 w-6 text-[#ff6464]" />

          </div>

          <div>

            <h3 className="text-lg font-semibold text-white">
              Media Converter {index + 1}
            </h3>

            <p className="text-sm text-gray-400">
              Configure physical LED mapping
            </p>

          </div>

        </div>

        {removable && (
          <button
            type="button"
            onClick={onRemove}
            className="rounded-xl border border-red-500/20 bg-red-500/10 p-2 transition hover:bg-red-500/20"
          >
            <Trash2 className="h-5 w-5 text-red-400" />
          </button>
        )}

      </div>

      {/* Converter ID */}

      <div className="mb-8">

        <Label className="mb-2 block text-gray-300">
          Converter ID
        </Label>

        <Input
          placeholder="MC-001"
          value={converter.mediaConverterId}
          onChange={(e) =>
            onIdChange(e.target.value)
          }
          className="border-[#333] bg-[#101010] text-white focus:border-[#8B0000]"
        />

      </div>

      {/* LED Mapping */}

      <LedMapping
        value={{
          left1Label: converter.left1Label,
          left2Label: converter.left2Label,
          left3Label: converter.left3Label,
          right1Label: converter.right1Label,
          right2Label: converter.right2Label,
          right3Label: converter.right3Label,
        }}
        onChange={onMappingChange}
      />

    </div>
  );
}